mutation loginWithoutDetails($email: String!, $password: String!) {
  tokenCreate(email: $email, password: $password) {
    refreshToken
    token
    errors {
      ...AccountErrorFragment
    }
    user {
      ...UserBaseFragment
    }
  }
}

fragment AccountErrorFragment on AccountError {
  code
  field
  message
}

fragment UserBaseFragment on User {
  id
  email
  firstName
  lastName
  isStaff
  userPermissions {
    code
    name
  }
}
